import{_ as r,c as o,o as e,ae as a}from"./chunks/framework.CliRSA9F.js";const i="/images/keyword_tracker_overview.webp",y=JSON.parse('{"title":"Keyword Tracker","description":"","frontmatter":{},"headers":[],"relativePath":"features/keyword-tracker.md","filePath":"features/keyword-tracker.md"}'),s={name:"features/keyword-tracker.md"};function n(l,t,p,d,c,u){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="keyword-tracker" tabindex="-1">Keyword Tracker <a class="header-anchor" href="#keyword-tracker" aria-label="Permalink to &quot;Keyword Tracker&quot;">​</a></h1><h2 id="monitor-and-optimize-your-podcast-s-visibility" tabindex="-1">Monitor and Optimize Your Podcast&#39;s Visibility <a class="header-anchor" href="#monitor-and-optimize-your-podcast-s-visibility" aria-label="Permalink to &quot;Monitor and Optimize Your Podcast&#39;s Visibility&quot;">​</a></h2><p>The Keyword Tracker is your ultimate tool to monitor the performance of your podcast across important search terms. It helps you track rankings, analyze trends, and refine your SEO strategy to outperform competitors. In the app&#39;s Search Visibility navigation, this feature appears as the <strong>Tracker</strong> tab (its full name is Keyword Tracker).</p><p><strong>Important</strong>: This feature works with the keywords you track from your <a href="https://podseo.com/help/keyword-strategy" target="_blank" rel="noreferrer">Keyword Strategy</a>. The Keyword Tracker is primarily for analyzing the performance of <em>already-tracked</em> keywords, but you can also add new keywords and delete existing ones directly on this page. For full keyword planning—organizing terms into Primary, Secondary, and Monitored tiers—the Keyword Strategy page remains your central hub.</p><p><img src="'+i+'" alt="Keyword Tracker Dashboard" width="600px" style="display:block;margin:0 auto;"></p><h3 id="features-at-a-glance" tabindex="-1"><strong>Features at a Glance</strong> <a class="header-anchor" href="#features-at-a-glance" aria-label="Permalink to &quot;**Features at a Glance**&quot;">​</a></h3><ol><li><p><strong>Track Keyword Performance Over Time</strong></p><ul><li><p>Visualize keyword ranking trends for your podcast across platforms like Spotify, Apple Podcasts, Amazon Music, and YouTube.</p></li><li><p>Interactive charts display how rankings shift over time, giving you insights into what’s working and what needs improvement.</p></li></ul></li><li><p><strong>View Current Rankings</strong></p><ul><li><p>Quickly check the current ranking for any keyword by clicking the <strong>rank icon</strong></p></li><li><p>This allows you to see exactly where your podcast or competitors rank for that keyword right now.</p></li></ul></li><li><p><strong>Compare Keywords</strong></p><ul><li><p>Track multiple keywords to identify which ones drive the most visibility and which need optimization</p></li><li><p>Spot trends across platforms and pinpoint growth opportunities.</p></li></ul></li><li><p><strong>Platform and Time Interval Filters</strong></p><ul><li><p>Switch between Spotify, Apple Podcasts, Amazon Music, and YouTube to analyze keyword performance on each platform.</p></li><li><p>Adjust the time interval (e.g., Last 30 Days) to focus on short-term trends or long-term growth.</p></li></ul></li><li><p><strong>Competitive Insights</strong></p><ul><li><p>See which podcasts rank for your tracked keywords and identify competitors dominating key search terms.</p></li><li><p>The table will dynamically add columns for each of your tracked competitors, allowing you to compare rankings side-by-side.</p></li></ul></li><li><p><strong>Popularity and Difficulty Metrics</strong></p><ul><li><p><strong>Popularity (POP.):</strong> Shows how many shows are ranking for the keyword, indicating its saturation.</p></li><li><p><strong>Difficulty (DIFF.):</strong> Measures how competitive it is to rank for the keyword, helping you prioritize achievable goals.</p></li></ul></li><li><p><strong>Top Results Modal</strong></p><ul><li>Click the &quot;Top Results&quot; button for any keyword to see the top 50 podcasts ranking for that keyword on the selected platform.</li></ul></li><li><p><strong>CSV Download</strong></p><ul><li>Download the currently filtered keyword data as a CSV file for your own analysis.</li></ul></li></ol><hr><h3 id="how-to-use" tabindex="-1"><strong>How to Use</strong> <a class="header-anchor" href="#how-to-use" aria-label="Permalink to &quot;**How to Use**&quot;">​</a></h3><ol><li><p><strong>Analyze Rankings</strong><br> Use the interactive chart to track trends over time. Hover over data points to view ranking details for specific dates.</p></li><li><p><strong>Check Current Rankings</strong><br> Click the <strong>rank icon</strong> (small icon with &quot;1, 2, 3&quot;) next to a keyword to instantly see the current ranking on supported platforms.</p></li><li><p><strong>Compare Competitors</strong><br> Scroll through the table to see which podcasts rank for each keyword. Identify and analyze competitors to refine your strategy.</p></li><li><p><strong>Filter Platforms and Keywords</strong><br> Use platform filters to focus on Spotify, Apple, Amazon Music, or YouTube data. Toggle individual keywords for more precise insights.</p></li></ol><hr><h3 id="why-it-matters" tabindex="-1"><strong>Why It Matters</strong> <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;**Why It Matters**&quot;">​</a></h3><p>The Keyword Tracker provides actionable insights into your podcast’s discoverability. With tools to track performance, compare competitors, and understand rankings across platforms, you can optimize your SEO strategy to grow your audience and outrank competitors.</p><hr><h3 id="pro-tip" tabindex="-1"><strong>Pro Tip</strong> <a class="header-anchor" href="#pro-tip" aria-label="Permalink to &quot;**Pro Tip**&quot;">​</a></h3><p>Click the <strong>rank icon</strong> often to stay up-to-date with your current keyword rankings. Use the insights to adapt your release schedules or metadata strategy to gain a competitive edge.</p><h3 id="plan-restrictions" tabindex="-1"><strong>Plan Restrictions</strong> <a class="header-anchor" href="#plan-restrictions" aria-label="Permalink to &quot;**Plan Restrictions**&quot;">​</a></h3><ul><li><strong>Primary Keywords</strong>: Maximum 3 across all plans (hard limit enforced).</li><li><strong>Secondary &amp; Monitored</strong>: The number of keywords you can track is based on your plan. If you exceed your plan&#39;s limit, you will see an &quot;Over-Quota Warning&quot;.</li><li><strong>Chart Display</strong>: All tracked keywords visible in performance charts.</li><li><strong>Historical Data</strong>: Access to keyword ranking trends over time is available on all plans, but the amount of historical data you can see may be limited on the free plan.</li></ul>',18)])])}const g=r(s,[["render",n]]);export{y as __pageData,g as default};
